package handlers
import (
 "fmt"
 "net/http"
 "strings"
 "time"
 "sort"
 "fluxo/models"
 "fluxo/services"
 "fluxo/utils"
 "github.com/gorilla/mux"
 "github.com/google/uuid"
)
func validTask(t *models.Tarefa,create bool)bool{t.Titulo=strings.TrimSpace(t.Titulo);if t.Titulo==""||len([]rune(t.Titulo))>200||len(t.Descricao)>10000||len(t.Anotacao)>2000||t.Prazo.IsZero(){return false};if _,err:=uuid.Parse(t.SetorID);err!=nil{return false};for _,id:=range []*string{t.ServidorID,t.RevisorID}{if id!=nil{if _,err:=uuid.Parse(*id);err!=nil{return false}}};if !contains([]string{"urgente","alta","media","baixa"},t.Prioridade)||!contains([]string{"Solicitação interna","Ouvidoria","Protocolo"},t.Origem){return false};return true}
func contains(list []string,value string)bool{for _,v:=range list{if v==value{return true}};return false}
func(a *API)allowed(w http.ResponseWriter,r *http.Request,id string)(models.Tarefa,bool){t,err:=a.Repo.Task(r.Context(),id);if err!=nil{utils.DBError(w,err);return t,false};u:=User(r);if u.Perfil!="gestor"&&t.SetorID!=u.SetorID&&(t.ServidorID==nil||*t.ServidorID!=u.ID)&&(t.RevisorID==nil||*t.RevisorID!=u.ID){utils.Error(w,403,"Você não tem acesso a esta tarefa.");return t,false};return t,true}
func(a *API)filtered(r *http.Request)([]models.Tarefa,error){tasks,err:=a.Repo.Tasks(r.Context(),User(r));if err!=nil{return nil,err};q:=r.URL.Query();result:=[]models.Tarefa{};for _,t:=range tasks{if q.Get("etapa")!=""&&q.Get("etapa")!=t.Etapa{continue};if q.Get("tipo_conteudo")!=""&&q.Get("tipo_conteudo")!=t.TipoConteudo{continue};if q.Get("canal")!=""&&q.Get("canal")!=t.Canal{continue};if q.Get("setor_id")!=""&&q.Get("setor_id")!=t.SetorID{continue};if q.Get("servidor_id")!=""&&(t.ServidorID==nil||*t.ServidorID!=q.Get("servidor_id")){continue};if q.Get("prioridade")!=""&&q.Get("prioridade")!=t.Prioridade{continue};if q.Get("status")!=""&&q.Get("status")!=t.Status{continue};if q.Get("busca")!=""&&!strings.Contains(strings.ToLower(t.Titulo+" "+t.Codigo),strings.ToLower(q.Get("busca"))){continue};if d:=q.Get("de");d!=""&&t.CriadoEm.Format("2006-01-02")<d{continue};if d:=q.Get("ate");d!=""&&t.CriadoEm.Format("2006-01-02")>d{continue};result=append(result,t)};return result,nil}
func(a *API)Tasks(w http.ResponseWriter,r *http.Request){if r.Method=="GET"{tasks,err:=a.filtered(r);if err!=nil{utils.DBError(w,err);return};utils.JSON(w,200,tasks);return};var t models.Tarefa;if !utils.Decode(w,r,&t){return};if !validTask(&t,true){utils.Error(w,400,"Verifique título, setor, prioridade, origem e prazo.");return};u:=User(r);if u.Perfil!="gestor"&&t.SetorID!=u.SetorID{utils.Error(w,403,"Crie tarefas apenas no seu setor.");return};saved,err:=a.Repo.SaveTask(r.Context(),t,u,true);if err!=nil{utils.DBError(w,err);return};utils.JSON(w,201,saved)}
func(a *API)Task(w http.ResponseWriter,r *http.Request){id:=mux.Vars(r)["id"];t,ok:=a.allowed(w,r,id);if !ok{return};switch r.Method{case "GET":utils.JSON(w,200,t);case "PUT":var updated models.Tarefa;if !utils.Decode(w,r,&updated){return};updated.ID=id;if !validTask(&updated,false){utils.Error(w,400,"Dados da tarefa inválidos.");return};saved,err:=a.Repo.SaveTask(r.Context(),updated,User(r),false);if err!=nil{utils.DBError(w,err);return};utils.JSON(w,200,saved);case "DELETE":if !manager(w,r){return};tx,err:=a.Repo.DB.Begin(r.Context());if err!=nil{utils.DBError(w,err);return};defer tx.Rollback(r.Context());rows,err:=tx.Query(r.Context(),"SELECT arquivo FROM anexos WHERE tarefa_id=$1",id);if err!=nil{utils.DBError(w,err);return};paths:=[]string{};for rows.Next(){var path string;if err=rows.Scan(&path);err!=nil{rows.Close();utils.DBError(w,err);return};paths=append(paths,path)};rows.Close();if err=rows.Err();err!=nil{utils.DBError(w,err);return};if _,err=tx.Exec(r.Context(),"DELETE FROM tarefas WHERE id=$1",id);err!=nil{utils.DBError(w,err);return};if err=tx.Commit(r.Context());err!=nil{utils.DBError(w,err);return};for _,path:=range paths{a.removeFile(path)};utils.JSON(w,204,nil)}}
func(a *API)Prioritaria(w http.ResponseWriter,r *http.Request){tasks,err:=a.filtered(r);if err!=nil{utils.DBError(w,err);return};open:=[]models.Tarefa{};for _,t:=range tasks{if t.Status!="concluida"{open=append(open,t)}};if len(open)==0{utils.JSON(w,200,nil);return};now:=time.Now();sort.SliceStable(open,func(i,j int)bool{return services.PriorityScore(open[i],now)>services.PriorityScore(open[j],now)});utils.JSON(w,200,map[string]any{"tarefa":open[0],"pontuacao":services.PriorityScore(open[0],now),"criterios":"Urgência, origem, tempo parado, prazo da etapa e publicação prevista"})}
func(a *API)History(w http.ResponseWriter,r *http.Request){id:=mux.Vars(r)["id"];if _,ok:=a.allowed(w,r,id);!ok{return};rows,err:=a.Repo.DB.Query(r.Context(),"SELECT id::text,tarefa_id::text,de_setor::text,para_setor::text,usuario_id::text,anotacao,data,etapa,prazo_etapa,responsavel_id::text FROM historicos_tarefa WHERE tarefa_id=$1 ORDER BY data",id);if err!=nil{utils.DBError(w,err);return};defer rows.Close();result:=[]models.Historico{};for rows.Next(){var h models.Historico;if err=rows.Scan(&h.ID,&h.TarefaID,&h.DeSetor,&h.ParaSetor,&h.UsuarioID,&h.Anotacao,&h.Data,&h.Etapa,&h.PrazoEtapa,&h.ResponsavelID);err!=nil{utils.DBError(w,err);return};result=append(result,h)};if err=rows.Err();err!=nil{utils.DBError(w,err);return};utils.JSON(w,200,result)}
func(a *API)Chat(w http.ResponseWriter,r *http.Request){id:=mux.Vars(r)["id"];if _,ok:=a.allowed(w,r,id);!ok{return};if r.Method=="POST"{var body struct{Mensagem string `json:"mensagem"`};if !utils.Decode(w,r,&body){return};body.Mensagem=strings.TrimSpace(body.Mensagem);if body.Mensagem==""||len([]rune(body.Mensagem))>4000{utils.Error(w,400,"Envie uma mensagem de até 4000 caracteres.");return};if _,err:=a.Repo.DB.Exec(r.Context(),"INSERT INTO chat_tarefa(tarefa_id,usuario_id,mensagem) VALUES($1,$2,$3)",id,User(r).ID,body.Mensagem);err!=nil{utils.DBError(w,err);return}};rows,err:=a.Repo.DB.Query(r.Context(),"SELECT id::text,tarefa_id::text,usuario_id::text,mensagem,data FROM chat_tarefa WHERE tarefa_id=$1 ORDER BY data",id);if err!=nil{utils.DBError(w,err);return};defer rows.Close();result:=[]models.Mensagem{};for rows.Next(){var m models.Mensagem;if err=rows.Scan(&m.ID,&m.TarefaID,&m.UsuarioID,&m.Mensagem,&m.Data);err!=nil{utils.DBError(w,err);return};result=append(result,m)};if err=rows.Err();err!=nil{utils.DBError(w,err);return};status:=200;if r.Method=="POST"{status=201};utils.JSON(w,status,result)}
func(a *API)Notifications(w http.ResponseWriter,r *http.Request){tasks,err:=a.Repo.Tasks(r.Context(),User(r));if err!=nil{utils.DBError(w,err);return};result:=[]map[string]any{};for _,t:=range tasks{if services.IsLate(t,time.Now()){result=append(result,map[string]any{"tarefa_id":t.ID,"titulo":t.Titulo,"tipo":"atraso","mensagem":fmt.Sprintf("Prazo vencido em %s",services.Deadline(t).Format("02/01/2006 15:04"))})}};utils.JSON(w,200,result)}
